function $(n,r="—"){if(n==null||n==="")return r;try{const t=new Date(n);if(isNaN(t.getTime())||t.getFullYear()<1970)return r;const f=new Date,o=f-t,e=Math.floor(o/6e4),s=Math.floor(o/36e5),u=Math.floor(o/864e5);if(e<1)return"Just now";if(e<60)return`${e} ${e===1?"minute":"minutes"} ago`;if(s<24)return`${s} ${s===1?"hour":"hours"} ago`;if(u<7)return`${u} ${u===1?"day":"days"} ago`;const i=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][t.getMonth()],a=t.getDate(),c=t.getFullYear();return c===f.getFullYear()?`${i} ${a}`:`${i} ${a}, ${c}`}catch{return r}}function m(n,r="—"){if(n==null||n==="")return r;try{const t=new Date(n);if(isNaN(t.getTime()))return r;const f=new Date;if(t<f)return $(n,r);const o=t-f,e=Math.floor(o/6e4),s=Math.floor(o/36e5),u=Math.floor(o/864e5);return e<60?`in ${e} ${e===1?"minute":"minutes"}`:s<24?`in ${s} ${s===1?"hour":"hours"}`:u<7?`in ${u} ${u===1?"day":"days"}`:`${["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][t.getMonth()]} ${t.getDate()}`}catch{return r}}export{m as a,$ as f};
